import{_ as t,o as n,c as a,a2 as i}from"./chunks/framework.vLhlLNVn.js";const r="/assets/daten-loeschen.BPFLrZkh.png",s="/assets/probleme-ohne-befund.r5E57PRA.png",l="/assets/probleme-periodenwechsel.CWhgzily.png",k=JSON.parse('{"title":"Betrieb und Wartung","description":"","frontmatter":{"order":5,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/02.anleitungen/05.betrieb-und-wartung.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/anleitungen/betrieb-und-wartung.md","filePath":"de/adapter/sourceanalytix/anleitungen/betrieb-und-wartung.md","lastUpdated":null}'),d={name:"de/adapter/sourceanalytix/anleitungen/betrieb-und-wartung.md"};function h(o,e,u,c,p,g){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="betrieb-und-wartung" tabindex="-1">Betrieb und Wartung <a class="header-anchor" href="#betrieb-und-wartung" aria-label="Permalink to &quot;Betrieb und Wartung&quot;">​</a></h1><p><a id="update-sourceanalytix-downgrade"></a></p><h2 id="wie-aktualisiere-ich-sourceanalytix-und-was-ist-ein-downgrade" tabindex="-1">Wie aktualisiere ich SourceAnalytix (und was ist ein Downgrade)? <a class="header-anchor" href="#wie-aktualisiere-ich-sourceanalytix-und-was-ist-ein-downgrade" aria-label="Permalink to &quot;Wie aktualisiere ich SourceAnalytix (und was ist ein Downgrade)?&quot;">​</a></h2><p>Wie jeden Adapter im Reiter „Adapter“, solange in den Systemeinstellungen das Repository „latest“ aktiv ist. In „stable“ ist SourceAnalytix noch nicht enthalten, dort siehst du kein Update. Werte und Einstellungen bleiben beim Update erhalten.</p><ol><li>Mach ein Backup.</li><li>Wähle in den Systemeinstellungen unter „Repositories“ „latest“.</li><li>Klicke im Reiter „Adapter“ bei SourceAnalytix auf den Update-Knopf.</li><li>Prüfe danach im Tab „Probleme“ der Instanz-Einstellungen, ob etwas gemeldet wird.</li></ol><p>Über die Konsole geht es mit <code>iobroker upgrade sourceanalytix</code>, ebenfalls nur mit „latest“. Bietet ioBroker kein Update an, prüfe die <a href="./../erste-schritte/installation#requirements-sourceanalytix-have-node-js">Voraussetzungen</a>. Nach einer Installation von GitHub zeigt Admin keine Updates; installiere dann einmal aus „latest“ darüber.</p><h3 id="downgrade" tabindex="-1">Downgrade <a class="header-anchor" href="#downgrade" aria-label="Permalink to &quot;Downgrade&quot;">​</a></h3><p>Ein Downgrade installiert eine ältere Version über die vorhandene, etwa wenn eine neue Version bei dir einen Fehler hat. Schalte im Reiter „Adapter“ den Expertenmodus ein und wähle bei SourceAnalytix „Bestimmte Version installieren“. In der Konsole: <code>iobroker upgrade sourceanalytix@&lt;Version&gt;</code>, ohne „v“ vor der Nummer.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Eine ältere Version kennt neuere Einstellungen nicht und schreibt Werte unter Umständen anders. Spiel im Zweifel das Backup ein, statt nur die Version zu wechseln.</p></div><p>Versionen mit Zusatz wie <code>-beta.0</code> sind Vorabversionen zum Testen. <code>0.8.0</code> ist neuer als <code>0.8.0-beta.0</code>.</p><p><strong>Siehe auch:</strong> <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#after-update-restore-values-0">Nach Update oder Restore sind Werte 0</a> · <a href="#data-back-up-move-new">Wo liegen die Daten?</a></p><p><a id="disable-datapoint-remove-sources-states"></a></p><h2 id="wie-schalte-ich-einen-datenpunkt-ab-oder-entferne-quellen-und-states" tabindex="-1">Wie schalte ich einen Datenpunkt ab oder entferne Quellen und States? <a class="header-anchor" href="#wie-schalte-ich-einen-datenpunkt-ab-oder-entferne-quellen-und-states" aria-label="Permalink to &quot;Wie schalte ich einen Datenpunkt ab oder entferne Quellen und States?&quot;">​</a></h2><p>Öffne die Quelle in den Instanz-Einstellungen und wähle bei „Aktionen“ „Deaktivieren“ oder „Daten löschen“. „Deaktivieren“ pausiert die Quelle, alles bleibt erhalten. „Daten löschen“ entfernt Ordner und Einstellungen endgültig.</p><table tabindex="0"><thead><tr><th></th><th>„Deaktivieren“</th><th>„Daten löschen“</th></tr></thead><tbody><tr><td>Ordner <code>sourceanalytix.0.&lt;Gerät&gt;</code> mit allen Jahren</td><td>bleibt</td><td>wird gelöscht</td></tr><tr><td>Einstellungen der Quelle (Preis, Startwerte, Offset)</td><td>bleiben</td><td>werden gelöscht</td></tr><tr><td>Rückgängig</td><td>mit „Aktivieren“</td><td>nicht möglich</td></tr></tbody></table><p>Beim Löschen zeigt der Dialog, was verschwindet. Zur Bestätigung tippst du den Namen der Quelle ein und klickst auf „Endgültig löschen“.</p><p><img src="'+r+'" alt="Dialog „Daten löschen“ mit der Liste der gelöschten Inhalte und dem Bestätigungsfeld"></p><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>„Daten löschen“ lässt sich nicht rückgängig machen. Willst du nur pausieren, nimm „Deaktivieren“.</p></div><h3 id="schalter-am-datenpunkt-im-reiter-„objekte" tabindex="-1">Schalter am Datenpunkt im Reiter „Objekte“ <a class="header-anchor" href="#schalter-am-datenpunkt-im-reiter-„objekte" aria-label="Permalink to &quot;Schalter am Datenpunkt im Reiter „Objekte“&quot;">​</a></h3><p>Den Schalter dort kannst du für mehrere Datenpunkte auf einmal ausschalten, etwa nach einer versehentlichen Massen-Aktivierung. Das entfernt die Einstellungen dieser Quellen samt Startwerten, die Ordner mit den Werten bleiben stehen. Zum Pausieren ist „Deaktivieren“ der richtige Weg.</p><h3 id="datenpunkt-geloscht" tabindex="-1">Datenpunkt gelöscht <a class="header-anchor" href="#datenpunkt-geloscht" aria-label="Permalink to &quot;Datenpunkt gelöscht&quot;">​</a></h3><p>Löschst du den Quell-Datenpunkt, schaltet SourceAnalytix die Quelle ab, die Werte bleiben. Der Tab „Probleme“ meldet „Datenpunkt existiert nicht mehr“. Ein Ordner ohne Datenpunkt steht in der Übersicht als „Ordner ohne Datenpunkt“ und lässt sich dort löschen.</p><h3 id="einzelne-perioden-entfernen" tabindex="-1">Einzelne Perioden entfernen <a class="header-anchor" href="#einzelne-perioden-entfernen" aria-label="Permalink to &quot;Einzelne Perioden entfernen&quot;">​</a></h3><p>Willst du etwa keine Quartale mehr, schalte die Option unter „Haupteinstellungen“ aus. Die Seite fragt nach, weil die States dieses Jahres gelöscht werden. Von Hand gelöschte States legt SourceAnalytix wieder an, solange die Option an ist.</p><p><strong>Siehe auch:</strong> <a href="#restart-datapoint-clean-up-old">Neu anfangen</a> · <a href="#data-back-up-move-new">Wo liegen die Daten?</a></p><p><a id="data-back-up-move-new"></a></p><h2 id="wo-liegen-die-daten-wie-sichere-ich-sie-und-ziehe-ich-um" tabindex="-1">Wo liegen die Daten, wie sichere ich sie und ziehe ich um? <a class="header-anchor" href="#wo-liegen-die-daten-wie-sichere-ich-sie-und-ziehe-ich-um" aria-label="Permalink to &quot;Wo liegen die Daten, wie sichere ich sie und ziehe ich um?&quot;">​</a></h2><p>In ioBroker selbst, eine eigene Datenbank gibt es nicht. Ein vollständiges ioBroker-Backup, etwa mit BackItUp, enthält alles. Für einen Umzug spielst du es auf dem neuen System ein, nicht kurz vor Mitternacht.</p><table tabindex="0"><thead><tr><th>Was</th><th>Wo</th></tr></thead><tbody><tr><td>Werte aller Perioden und Jahre</td><td>Ordner <code>sourceanalytix.0.&lt;Gerät&gt;</code></td></tr><tr><td>Einstellungen der Quelle mit Startwerten und Offset</td><td>Objekt des Quell-Datenpunkts, <code>common.custom.sourceanalytix.0</code></td></tr><tr><td>Preisdefinitionen und Optionen</td><td>Instanz-Einstellungen</td></tr><tr><td>Preisverlauf</td><td><code>sourceanalytix.0.priceHistory</code> und <code>basicPriceHistory</code></td></tr><tr><td>Aufgezeichnete Verläufe</td><td>dein History-Adapter</td></tr></tbody></table><p>Ein Backup nur von <code>sourceanalytix.0</code> reicht nicht, denn Startwerte und Offset stehen am Quell-Datenpunkt. Läuft ioBroker mit Redis, gehört die Redis-Sicherung dazu.</p><h3 id="umzug-auf-neue-hardware" tabindex="-1">Umzug auf neue Hardware <a class="header-anchor" href="#umzug-auf-neue-hardware" aria-label="Permalink to &quot;Umzug auf neue Hardware&quot;">​</a></h3><ol><li>Mach auf dem alten System ein vollständiges Backup.</li><li>Installiere auf dem neuen System ioBroker und SourceAnalytix und spiel das Backup ein.</li><li>Starte die Instanz. Verpasste Periodenwechsel holt sie einmal nach.</li><li>Prüfe den Tab „Probleme“ und vergleiche den Gesamtstand mit deinem Zähler.</li></ol><p><img src="'+s+'" alt="Tab „Probleme“ ohne Befund"></p><p>Quellen auf dem neuen System neu anzulegen, ersetzt den Restore nicht: SourceAnalytix beginnt dann bei 0. Bekommt der Datenpunkt eine neue ID, ist er eine neue Quelle; der alte Ordner bleibt als Archiv.</p><p><strong>Siehe auch:</strong> <a href="#iobroker-was-down-midnight-recover">ioBroker war um Mitternacht aus</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#after-update-restore-values-0">Werte nach Restore 0</a></p><p><a id="restart-datapoint-clean-up-old"></a></p><h2 id="wie-fange-ich-mit-einem-datenpunkt-neu-an-und-raume-alte-jahre-auf" tabindex="-1">Wie fange ich mit einem Datenpunkt neu an und räume alte Jahre auf? <a class="header-anchor" href="#wie-fange-ich-mit-einem-datenpunkt-neu-an-und-raume-alte-jahre-auf" aria-label="Permalink to &quot;Wie fange ich mit einem Datenpunkt neu an und räume alte Jahre auf?&quot;">​</a></h2><p>Lösche die Daten der Quelle mit „Daten löschen“ und lege sie mit „Quelle hinzufügen“ neu an, mit „Ab jetzt zählen“. Alle Perioden beginnen dann bei 0. Nur den Ordner im Reiter „Objekte“ zu löschen reicht nicht, denn die Einstellungen am Datenpunkt bleiben.</p><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Damit ist auch der bisherige Gesamtstand weg. Willst du nur falsche Zahlen reparieren, nimm <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Zählerstand angleichen</a>.</p></div><h3 id="alte-jahre-aufraumen" tabindex="-1">Alte Jahre aufräumen <a class="header-anchor" href="#alte-jahre-aufraumen" aria-label="Permalink to &quot;Alte Jahre aufräumen&quot;">​</a></h3><p>Ordner abgeschlossener Jahre wie <code>sourceanalytix.0.&lt;Gerät&gt;.2023</code> sind reine Historie. Du darfst sie im Reiter „Objekte“ löschen. Lass <code>currentYear</code>, <code>cumulativeReading</code>, <code>periodMemory</code> und den Ordner des laufenden Jahres stehen. „Kosten ab Datum neu rechnen“ lässt gelöschte Jahre aus.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">Startwerte</a> · <a href="./werte-auswerten#evaluate-across-years-adjusting-everything">Über mehrere Jahre auswerten</a></p><p><a id="iobroker-was-down-midnight-recover"></a></p><h2 id="iobroker-war-um-mitternacht-aus-–-wie-hole-ich-den-tageswechsel-nach" tabindex="-1">ioBroker war um Mitternacht aus – wie hole ich den Tageswechsel nach? <a class="header-anchor" href="#iobroker-war-um-mitternacht-aus-–-wie-hole-ich-den-tageswechsel-nach" aria-label="Permalink to &quot;ioBroker war um Mitternacht aus – wie hole ich den Tageswechsel nach?&quot;">​</a></h2><p>Meist gar nicht. SourceAnalytix holt verpasste Wechsel beim Start selbst nach und prüft außerdem jede Stunde, ob einer fehlt. Den Verbrauch über Mitternacht teilt es nach der Zeit auf den alten und den neuen Tag auf.</p><p>Fehlt trotzdem ein Wechsel, meldet der Tab „Probleme“ „Periodenwechsel verpasst“ mit „Nachholen“. Dasselbe geht bei der Quelle mit der Aktion „Perioden nachholen“. Beides wirkt nur auf diese Quelle.</p><p><img src="'+l+`" alt="Tab „Probleme“ mit „Periodenwechsel verpasst“ und dem Knopf „Nachholen“"></p><p>Hat der Ausfall mehrere Tage gedauert, verarbeitet SourceAnalytix nur einen Wechsel; die Tage dazwischen bekommen keinen eigenen Wert. Werte, die während eines Wechsels kommen, werden danach in ihrer Reihenfolge verarbeitet.</p><h3 id="per-skript-oder-knopf-in-vis" tabindex="-1">Per Skript oder Knopf in VIS <a class="header-anchor" href="#per-skript-oder-knopf-in-vis" aria-label="Permalink to &quot;Per Skript oder Knopf in VIS&quot;">​</a></h3><p>Schreibe <code>true</code> in <code>sourceanalytix.0.info.recoverPeriods</code>, dann holt SourceAnalytix die Wechsel aller Quellen nach. Aus einem Skript geht es auch für eine Quelle:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sourceanalytix.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;recoverPeriods&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {source: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;ID des Quell-Datenpunkts&gt;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (result.error) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result.message, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;warn&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Ohne <code>source</code> gilt der Aufruf für alle Quellen. Der Wechsel richtet sich nach der Systemzeit des ioBroker-Rechners; stimmt dort die Zeitzone nicht, wechselt SourceAnalytix zur falschen Stunde.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Gestern, letzte Woche, letzter Monat</a> · <a href="./../fehlerbehebung/log-meldungen#midnight-crash-rollover-wrong-time">Wechsel zur falschen Zeit</a></p>`,53)])])}const b=t(d,[["render",h]]);export{k as __pageData,b as default};
